/**
 * Repoints every issue carrying `sourceLabelId` onto `targetLabelId` and
 * drops the source label. Issues already carrying both would collide on the
 * `issue_labels` unique index, so those duplicate rows are dropped first
 * instead of updated. Returns how many issues carried the source label.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  const db = getDb();

  const sourceRows = db
    .select({ issueId: issueLabels.issueId })
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, sourceLabelId),
      ),
    )
    .all();

  const targetRows = db
    .select({ issueId: issueLabels.issueId })
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, targetLabelId),
      ),
    )
    .all();
  const targetIssueIds = new Set(targetRows.map((row) => row.issueId));

  const duplicateIssueIds = sourceRows
    .map((row) => row.issueId)
    .filter((issueId) => targetIssueIds.has(issueId));

  if (duplicateIssueIds.length > 0) {
    db.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
          inArray(issueLabels.issueId, duplicateIssueIds),
        ),
      )
      .run();
  }

  db.update(issueLabels)
    .set({ labelId: targetLabelId })
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, sourceLabelId),
      ),
    )
    .run();

  db.delete(labels)
    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
    .run();

  return sourceRows.length;
}

/** Replaces the whole label set of one issue in a single round trip. */

